
import type { ReturnShipmentLineItemAllocation } from './ReturnShipmentLineItemAllocation.js';
import type { ShippingDimensions } from './ShippingDimensions.js';
import type { ShippingWeight } from './ShippingWeight.js';

export type CreatePackageRequest = { /** Controls buyer email handling. Omit or use send to send when recipient, template, and deduplication rules allow it. Use suppress when another system owns buyer messaging. On create, tracking fields also record an initial tracking_updated fulfillment event; tracking PATCH requests always record tracking_updated events. */ "buyer_notification_behavior"?: "send" | "suppress" | (string & {}); "carrier"?: string; "dimensions"?: ShippingDimensions; /** Caller-owned identifier for this resource in an external system. Caller-owned package identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. minLength: 1. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this package. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; /** Merchant or integration supplied HTTPS shipping-label URL for authenticated merchant workflows. Non-Flint URLs must include external_system for provenance. Flint does not currently manage label file hosting or buyer-facing label downloads. */ "label_url"?: string; "metadata"?: Record<string, string>; /** Required for a package on a return shipment: allocates quantities from the shipment's return_line_items to this parcel. Rejected on outbound shipments. */ "return_line_items"?: Array<ReturnShipmentLineItemAllocation>; "service_code"?: string; "status_reason"?: string; "tracking_number"?: string; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. */ "tracking_url"?: string; "weight"?: ShippingWeight; };
